def process_batch_with_dlq(records, sink, dlq, checkpoint_store, partition, max_retries=3):
    for rec in records:
        delivered = False
        for attempt in range(max_retries):
            try:
                sink.write_idempotent(rec.idempotency_key, rec.payload)
                delivered = True
                break
            except TransientSinkError:
                backoff = min(2.0, (0.05 * (2 ** attempt)) + random.uniform(0, 0.05))
                time.sleep(backoff)
            except SchemaValidationError as err:
                dlq.publish(partition, rec.offset, rec.payload, reason=str(err))
                delivered = True  # Diverted to DLQ; safe to advance offset
                break
        if not delivered:
            dlq.publish(partition, rec.offset, rec.payload, reason='max_retries_exhausted')
        checkpoint_store.commit_offset(partition, rec.offset + 1)
